def investigate(context, acquire):
    history = acquire("history")
    actions = context.get("actions", [])
    goal = context.get("goal")

    def simulate(seq):
        committed = {}
        main_tx = False
        other_tx = False
        main_pending = {}
        other_pending = {}
        last_main_changes = 0
        for act in seq:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                if conn == "main":
                    main_tx = True
                    main_pending = {}
                else:
                    other_tx = True
                    other_pending = {}
            elif op == "commit":
                if conn == "main":
                    committed.update(main_pending)
                    main_tx = False
                    main_pending = {}
                else:
                    committed.update(other_pending)
                    other_tx = False
                    other_pending = {}
            elif op == "rollback":
                if conn == "main":
                    main_tx = False
                    main_pending = {}
                else:
                    other_tx = False
                    other_pending = {}
            elif op == "put":
                key = act.get("key")
                val = act.get("value")
                target = main_pending if (conn == "main" and main_tx) else (other_pending if (conn == "other" and other_tx) else committed)
                if key in target:
                    changes = 0
                else:
                    target[key] = val
                    changes = 1
                if conn == "main":
                    last_main_changes = changes
            elif op == "update":
                key = act.get("key")
                val = act.get("value")
                target = main_pending if (conn == "main" and main_tx) else (other_pending if (conn == "other" and other_tx) else committed)
                if key in target:
                    target[key] = val
                    changes = 1
                else:
                    changes = 0
                if conn == "main":
                    last_main_changes = changes
            elif op == "delete":
                key = act.get("key")
                target = main_pending if (conn == "main" and main_tx) else (other_pending if (conn == "other" and other_tx) else committed)
                if key in target:
                    del target[key]
                    changes = 1
                else:
                    changes = 0
                if conn == "main":
                    last_main_changes = changes
        return committed, last_main_changes

    committed, last_main_changes = simulate(actions)

    if goal == "committed_count":
        return {"value": len(committed), "unresolved": False}
    if goal == "committed_sum":
        return {"value": sum(committed.values()), "unresolved": False}
    if goal == "channel":
        return {"value": last_main_changes, "unresolved": False}
    return {"value": None, "unresolved": True}

